{name="42-44 Riverglades",lo=42,hi=44,next="43-44 Tanaris",tips={
[2]={"Click on the Tanning Rack behind the boat."},
[3]={"Buy 1 [Fresh Chum] for 80 silver."},
[4]={"Click on the Wanted Poster."},
[12]={"Buy 1 [Expired Poison] for 15 silver."},
[13]={"Buy 1 [Goblin Degreaser] for 40 silver."},
[16]={"Kill Trapclaw. Loot it for [Trapclaw's Pincer].","Skip this step if Trapclaw is not there."},
[17]={"Kill Shore Crawlers. Loot them for [Crawler Spittle], [Sand Crawler Meat], and [Beast Entrails]."},
[18]={"Kill Musketeers and Buccaneers. Loot them for [Smuggled Goods]."},
[20]={"Kill Trapclaw. Loot it for [Trapclaw's Pincer].","Skip this step if Trapclaw is not there."},
[21]={"Kill Beasts or Shore Crawler. Loot them for [Beast Entrails]."},
[24]={"Kill Eastsea Raiders and Eastsea Bombardiers around Windstead."},
[25]={"Click on the Eastsea Powder Kegs around Windstead."},
[26]={"Kill Eastsea Raiders and Eastsea Bombardiers around Windstead."},
[28]={"Kill Beasts or Shore Crawler. Loot them for [Beast Entrails]."},
[35]={"Kill Beasts or Shore Crawler. Loot them for [Beast Entrails]."},
[36]={"Kill Trapclaw. Loot it for [Trapclaw's Pincer].","Complete this objective now if you skipped it earlier."},
[39]={"Click on the Cannon Ammunition on the ship's second level.","Try using your Interact key from the ship's first level to interact with the Cannon Ammunition on the second level.","You may need to angle your camera so you can see inside the ship."},
[40]={"Kill Admiral Lamora. Loot him for [Lamora's Key].","Be careful: he patrols the entire first floor of the ship."},
[41]={"Click on the Cannon Ammunition on the ship's second level."},
[42]={"Click on the Chest on the ship's lowest level."},
[43]={"Click on the Cannon Ammunition on the ship's second level.","Try using your Interact key from the ship's first level to interact with the Cannon Ammunition on the second level.","You may need to angle your camera so you can see inside the ship."},
[45]={"Click on the Rotflesh Mushrooms inside the cave near Windstead."},
[47]={"Click on the Rotflesh Mushrooms inside the cave near Windstead."},
[49]={"Kill Komuk along the marked patrol route. Loot him for [Komuk's Warmaul].","Komuk is an elite. Group up or skip this step if you cannot defeat him.","Click on [Komuk's Warmaul] in your bags to accept the quest."},
[51]={"Click on [Komuk's Warmaul] in the Active Items window to accept the quest."},
[52]={"If Dunston Willis is away escorting another player, kill nearby ogres while waiting for him to return."},
[53]={"Kill Gronok the Butcher inside the building. Loot him for [Gronok's Key]."},
[54]={"The next quest starts an escort. Consider clearing nearby enemies before accepting it especially the patrols."},
[55]={"Escort Dunston Willis out of Bolder'ok. Protect him from attackers.","Kill the patrols before Dunston Willis reaches another group of enemies."},
[56]={"Kill Komuk along the marked patrol route. Loot him for [Komuk's Warmaul].","Komuk is an elite. Group up or skip this step if you cannot defeat him.","Click on [Komuk's Warmaul] in your bags to accept the quest."},
[58]={"Kill Ghostmaw. Loot it for [Ghostmaw's Fang].","Ghostmaw is an elite crocodile that can be anywhere along the riverbank. Group up or skip this quest if he is too difficult.","You'll have more chances to kill him later."},
[59]={"Kill Rog'mar Trainees and Blademaster Kaijo. Loot him for [Blademaster's Banner].","Blademaster Kaijo is an elite. Group up or skip this quest if you cannot defeat him.","Click on the Rog'mar Supply Crates around the camps."},
[60]={"Kill Krek the Noxious at the waterfall.","Krek the Noxious is an elite. Group up or skip this quest if you cannot defeat him."},
[61]={"Click on [Komuk's Warmaul] in the Active Items window to accept the quest."},
[62]={"Kill Rog'mar Trainees and Blademaster Kaijo. Loot him for [Blademaster's Banner].","Blademaster Kaijo is an elite. Group up or skip this quest if you cannot defeat him.","Click on the Rog'mar Supply Crates around the camps."},
